def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # Maps key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries
            expired_keys = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
            for k in expired_keys:
                del cache[k]

            # If key exists, remove it (will re-add at end to mark as most recently used)
            if key in cache:
                del cache[key]
            else:
                # Key is new; if cache is full, evict LRU
                if len(cache) >= capacity:
                    cache.popitem(last=False)  # Remove oldest (first) item

            # Add/update the key as most recently used
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            expired_keys = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
            for k in expired_keys:
                del cache[k]

            # Get the value
            if key in cache:
                value, wt = cache[key]
                results.append(value)
                # Mark as most recently used by removing and re-adding
                del cache[key]
                cache[key] = (value, wt)
            else:
                results.append(-1)

    return results

